            quillonL.rotation.z = 0.55;
            swordRoot.add(quillonL);

            const quillonR = new THREE.Mesh(new THREE.ConeGeometry(0.045, 0.12, 6), this.goldTrimMat);
            quillonR.position.set(0.24, 0.03, 0);
