        // Ancient Gnarled Tree Trunk
        const trunk = new THREE.Mesh(new THREE.CylinderGeometry(1.6, 2.4, 4.5, 10), woodMat);
        trunk.castShadow = true;
        bodyGroup.add(trunk);

        // Sweeping Scythe Branches
        const rightShoulder = new THREE.Group();
