        hornL.rotation.y = 0.5;
        headGroup.add(hornL);

        const hornR = new THREE.Mesh(new THREE.TorusGeometry(0.8, 0.15, 6, 12, Math.PI), maskMat);
        hornR.position.set(1.1, 0.6, 0);
        hornR.rotation.y = -0.5;
