    // 13. TORTURE WHEEL SKELETON
    createWheelSkeletonMob(x, z, angle = 0, y = 0, mobDef = null) {
        const root = new THREE.Group();
        root.position.set(x, y, z);
        root.rotation.y = angle;

        const bodyGroup = new THREE.Group();
        bodyGroup.position.y = 0.85;
        root.add(bodyGroup);

        const torso = new THREE.Group();
        bodyGroup.add(torso);

        const boneMat = this.bonePaleMat || this.boneMat;
        const woodMat = this.woodTorchMat || this.woodMat;
        const ironMat = this.darkSteelMat;

        // Medieval Torture Wheel Frame (Torus + Spokes)
        const wheel = new THREE.Group();
        wheel.position.set(0, 0, 0);
        torso.add(wheel);

        const rim = new THREE.Mesh(new THREE.TorusGeometry(0.68, 0.08, 8, 20), woodMat);
        rim.castShadow = true;
        wheel.add(rim);

        // 8 Spokes
        for (let s = 0; s < 4; s++) {
            const spoke = new THREE.Mesh(new THREE.CylinderGeometry(0.04, 0.04, 1.36, 6), woodMat);
            spoke.rotation.z = (s / 4) * Math.PI;
            wheel.add(spoke);
        }

        // 16 Outward Spikes on Rim
        for (let k = 0; k < 16; k++) {
            const ang = (k / 16) * Math.PI * 2;
            const spike = new THREE.Mesh(new THREE.ConeGeometry(0.05, 0.24, 4), ironMat);
            spike.position.set(Math.cos(ang) * 0.78, Math.sin(ang) * 0.78, 0);
            spike.rotation.z = ang - Math.PI / 2;
            wheel.add(spike);
        }

        // Sculpted High-Detail Human Skull Peering Through Upper Spokes
        const headGroup = new THREE.Group();
        headGroup.position.set(0, 0.38, 0.14);
        torso.add(headGroup);

        // Cranium vault
        const cranium = new THREE.Mesh(new THREE.SphereGeometry(0.13, 10, 8), boneMat);
        cranium.scale.set(0.92, 1.05, 1.12);
        cranium.castShadow = true;
        headGroup.add(cranium);

        // Brow Ridge & Zygomatic Arches (Cheekbones)
        const brow = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.04, 0.08), boneMat);
        brow.position.set(0, 0.04, 0.11);
        headGroup.add(brow);

        [-0.08, 0.08].forEach(cx => {
            const cheek = new THREE.Mesh(new THREE.BoxGeometry(0.04, 0.08, 0.06), boneMat);
            cheek.position.set(cx, -0.04, 0.10);
            headGroup.add(cheek);
        });

        // Sunken Orbital Sockets with glowing crimson death embers
        const emberMat = this.emberGlowMat || new THREE.MeshBasicMaterial({ color: 0xff2200 });
        [-0.05, 0.05].forEach(ex => {
            const socket = new THREE.Mesh(new THREE.SphereGeometry(0.032, 6, 6), this.darkSteelMat);
            socket.position.set(ex, 0.01, 0.11);
            headGroup.add(socket);

            const emberEye = new THREE.Mesh(new THREE.SphereGeometry(0.016, 4, 4), emberMat);
            emberEye.position.set(ex, 0.01, 0.13);
            headGroup.add(emberEye);
        });

        // Nasal Cavity
        const noseCavity = new THREE.Mesh(new THREE.BoxGeometry(0.03, 0.045, 0.03), this.darkSteelMat);
        noseCavity.position.set(0, -0.03, 0.13);
        headGroup.add(noseCavity);

        // Maxilla & Snapping Mandible with teeth
        const jaw = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.06, 0.10), boneMat);
        jaw.position.set(0, -0.10, 0.07);
        jaw.rotation.x = 0.18;
        headGroup.add(jaw);

        // Individual teeth
        for (let t = -3; t <= 3; t++) {
            const tooth = new THREE.Mesh(new THREE.BoxGeometry(0.012, 0.022, 0.012), boneMat);
            tooth.position.set(t * 0.016, -0.07, 0.11);
            headGroup.add(tooth);
        }

        // Cervical Spine Vertebrae connecting head to hub
        for (let v = 0; v < 3; v++) {
            const vert = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.035, 0.05, 6), boneMat);
            vert.position.set(0, -0.14 - v * 0.055, 0.02 - v * 0.01);
            headGroup.add(vert);
        }

        // Ribcage strapped across wheel hub
        const ribcage = new THREE.Group();
        ribcage.position.set(0, 0.05, 0.02);
        torso.add(ribcage);
        for (let r = 0; r < 4; r++) {
            const rib = new THREE.Mesh(new THREE.TorusGeometry(0.18 - r * 0.015, 0.02, 4, 8, Math.PI), boneMat);
            rib.position.y = -r * 0.08;
            rib.rotation.x = Math.PI;
            ribcage.add(rib);
        }

        // Bone Arms Strapped to Wheel Spokes
        const rightShoulder = new THREE.Group();
        rightShoulder.position.set(0.35, 0.15, 0.1);
        torso.add(rightShoulder);
        const rArm = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.05, 0.65, 6), boneMat);
        rArm.position.y = -0.28;
        rightShoulder.add(rArm);

        const leftShoulder = new THREE.Group();
        leftShoulder.position.set(-0.35, 0.15, 0.1);
        torso.add(leftShoulder);
        const lArm = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.05, 0.65, 6), boneMat);
        lArm.position.y = -0.28;
        leftShoulder.add(lArm);

        const rightHip = new THREE.Group();
        rightHip.position.set(0.22, -0.55, 0.05);
        torso.add(rightHip);
        const rLeg = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.05, 0.45, 6), boneMat);
        rLeg.position.y = -0.2;
        rightHip.add(rLeg);

        const leftHip = new THREE.Group();
        leftHip.position.set(-0.22, -0.55, 0.05);
        torso.add(leftHip);
        const lLeg = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.05, 0.45, 6), boneMat);
        lLeg.position.y = -0.2;
        leftHip.add(lLeg);

        root.userData = {
            def: mobDef,
            bodyGroup, torso, head: headGroup,
            rightShoulder, leftShoulder, rightHip, leftHip,
            rightArm: rightShoulder, leftArm: leftShoulder,
            rightLeg: rightHip, leftLeg: leftHip,
            weapon: rim
        };
        this.scene.add(root);
        return root;
    }

