        const crown = new THREE.Mesh(new THREE.ConeGeometry(0.24, 0.7, 6), silverCrownMat);
        crown.position.y = 0.25;
        headGroup.add(crown);

        const faceVeil = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.22, 0.45, 8), veilMeshMat);
