        const goldArmorMat = new THREE.MeshStandardMaterial({ color: 0xd4af37, metalness: 0.92, roughness: 0.22 });
        const scarletHairMat = new THREE.MeshStandardMaterial({ color: 0xb3132c, roughness: 0.7 });
