        // Smooth Faceless Liquid Head
        const headGroup = new THREE.Group();
        headGroup.position.set(0, 0.65, 0);
        torso.add(headGroup);

        const head = new THREE.Mesh(new THREE.SphereGeometry(0.25, 16, 16), mercuryMat);
        head.scale.set(0.9, 1.15, 0.95);
