        const morphBlade = new THREE.Mesh(new THREE.ConeGeometry(0.18, 1.8, 12), mercuryCoreMat);
        morphBlade.position.set(0.15, -0.2, 0.95);
        morphBlade.rotation.x = 1.35;
        morphBlade.rotation.z = -0.2;
        rightShoulder.add(morphBlade);

        // Left Arm: Fluid Claw
