        const goldArmorMat = new THREE.MeshStandardMaterial({ color: 0xd4af37, metalness: 0.9, roughness: 0.25 });
        const scarletMat = new THREE.MeshStandardMaterial({ color: 0xb91c1c, roughness: 0.8 });
