        // Heavy Angelic Halberd
        const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.06, 3.4, 8), goldPlateMat);
        pole.position.set(0.65, 0.4, 0.25);
        pole.rotation.x = 0.2;
