            bodyGroup.add(leg1);

            const leg2 = new THREE.Mesh(new THREE.ConeGeometry(0.22, 1.4, 6), metyrFleshMat);
            leg2.position.set(fx * 1.45, -1.2, fz * 1.45);
            leg2.rotation.x = Math.PI;
            bodyGroup.add(leg2);
